// Bakes each shipped hull's engine nozzles and gun barrels (the named sockets
// in the approved LOD2 GLBs) into src/ship-hardpoints.generated.ts, in exactly
// the model space the battle viewer draws: ship-model-stage's loadShipModel
// (centred, nose toward -Z, nose-to-tail length 2). The flat battle art and the
// 3D hulls share these points, so effects leave the same place on both.
//   node scripts/build-ship-hardpoints.mjs          rewrite the generated file
//   node scripts/build-ship-hardpoints.mjs --check  fail when it is stale
import { readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import vm from "node:vm";
import ts from "typescript";
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";

const OUT = new URL("../src/ship-hardpoints.generated.ts", import.meta.url);
const source = name => readFileSync(new URL(`../src/${name}.ts`, import.meta.url), "utf8");
function compile(name, deps = {}, extra = {}) {
  const exports = {};
  vm.runInNewContext(ts.transpileModule(source(name), { compilerOptions: {
    target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS,
  } }).outputText, { exports, require: id => {
    if (!(id in deps)) throw new Error(`unexpected dependency ${id}`);
    return deps[id];
  }, console, ...extra });
  return exports;
}

// Geometry only: texture decoding needs a browser and never moves a socket.
class GeometryLoader extends GLTFLoader {
  constructor() {
    super();
    this.register(parser => ({ name: "HARDPOINTS_GEOMETRY_ONLY", beforeRoot() { parser.assignTexture = () => Promise.resolve(null); } }));
  }
}
const catalog = compile("ship-models.generated");
const stage = compile("ship-model-stage", { three: THREE,
  "three/addons/loaders/GLTFLoader.js": { GLTFLoader: GeometryLoader },
  "three/addons/environments/RoomEnvironment.js": { RoomEnvironment: class {} }, "./ship-models.generated": catalog,
}, { fetch: async url => {
  const bytes = readFileSync(new URL(`../public${url.split("?")[0]}`, import.meta.url));
  return { ok: true, arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) };
} });

const round = v => Math.round(v * 1e4) / 1e4 || 0; // never a negative zero

/** The hardpoints of one hull as loadShipModel returns it. */
export function hardpointsOf(model) {
  model.updateMatrixWorld(true);
  const size = new THREE.Box3().setFromObject(model).getSize(new THREE.Vector3());
  const found = { engine: [], weapon: [], turret: [] };
  const at = new THREE.Vector3();
  model.traverse(node => {
    // GLTFLoader strips dots from node.name; the authored name survives here.
    const name = node.userData.name ?? node.name;
    const role = /^socket\.(engine|weapon|turret)\./.exec(name)?.[1];
    if (!role) return;
    node.getWorldPosition(at);
    found[role].push([name, [round(at.x), round(at.y), round(at.z)]]);
  });
  const points = list => list.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)).map(entry => entry[1]);
  return {
    size: [round(size.x), round(size.y), round(size.z)],
    engines: points(found.engine),
    guns: points(found.weapon.length ? found.weapon : found.turret),
  };
}

export async function extractHardpoints() {
  const table = {};
  for (const kind of Object.keys(catalog.SHIP_MODELS)) {
    const model = await stage.loadShipModel(kind);
    table[kind] = hardpointsOf(model);
    stage.disposeModel(model);
  }
  return table;
}

export function renderHardpoints(table) {
  const list = points => `[${points.map(p => `[${p.join(", ")}]`).join(", ")}]`;
  const rows = Object.entries(table).map(([kind, h]) =>
    `  "${kind}": {\n    size: [${h.size.join(", ")}],\n    engines: ${list(h.engines)},\n    guns: ${list(h.guns)},\n  },`);
  return `// Generated by scripts/build-ship-hardpoints.mjs from the shipped LOD2 hulls.
// Model space exactly as the battle viewer loads a hull (ship-model-stage's
// loadShipModel): centred, nose toward -Z, nose-to-tail length 2. Points are
// [x, y, z]: engine nozzle sockets, and gun barrel sockets (turret mounts when
// a hull has no barrels). size is the hull's bounding box [x, y, z].
import type { ShipKind } from "./protocol";

export type HardpointXYZ = readonly [number, number, number];

export interface ShipHardpoints {
  readonly size: HardpointXYZ;
  readonly engines: readonly HardpointXYZ[];
  readonly guns: readonly HardpointXYZ[];
}

export const SHIP_HARDPOINTS: Record<ShipKind, ShipHardpoints> = {
${rows.join("\n")}
};
`;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const text = renderHardpoints(await extractHardpoints());
  if (process.argv.includes("--check")) {
    if (readFileSync(OUT, "utf8") !== text) {
      console.error("src/ship-hardpoints.generated.ts is stale: run npm run assets:hardpoints");
      process.exit(1);
    }
    console.log("Ship hardpoints: the generated table matches the shipped hulls.");
  } else {
    writeFileSync(OUT, text);
    console.log(`Wrote ${OUT.pathname}`);
  }
}
